const results = [];

const inputs = $('Edit Fields').first().json;

for (const item of $input.all()) {
  let response = item.json.output ?? item.json;

  if (typeof response === 'string') {
    response = response.trim()
      .replace(/^```(?:json)?\s*/i, '')
      .replace(/\s*```$/, '');

    response = JSON.parse(response);
  }

  if (!Array.isArray(response.competitors)) {
    throw new Error('Missing competitors array');
  }

  for (const competitor of response.competitors) {
    results.push({
      json: {
        target_company: inputs.company,
        industry: inputs.industry,
        news_days: inputs.news_days,
        competitor_count: inputs.competitor_count,
        ...competitor
      }
    });
  }
}

return results;

const results = [];

for (const item of $input.all()) {
  let data = item.json.output ?? item.json;

  if (typeof data === 'string') {
    data = data.trim()
      .replace(/^```(?:json)?\s*/i, '')
      .replace(/\s*```$/, '');

    data = JSON.parse(data);
  }

  if (!data.company_name) {
    throw new Error('Missing company name in Agent 3 output');
  }

  results.push({
    json: {
      company_name: data.company_name,
      competing_product: data.competing_product,
      pricing: data.pricing,
      core_features: data.core_features,
      target_customers: data.target_customers,
      market_positioning: data.market_positioning,
      recent_news: data.recent_news,
      source_urls: data.source_urls
    }
  });
}

return results;

const competitors = $('Parse Competitor JSON').all();
const products = $('Agent 2 - Product Research').all();
const news = $input.all();

if (
  competitors.length !== products.length ||
  competitors.length !== news.length
) {
  throw new Error(
    'Competitor, product and news counts do not match'
  );
}

return competitors.map((item, i) => {
  const competitor = item.json;
  const productData = products[i].json;
  const newsData = news[i].json;

  const company = String(competitor.company_name).toLowerCase();
  const product = String(competitor.competing_product).toLowerCase();

  // Check that each search relates to the competitor
  const productQuery = String(productData.query || '').toLowerCase();
  const newsQuery = String(newsData.query || '').toLowerCase();

  if (
    !productQuery.includes(company) ||
    !newsQuery.includes(company)
  ) {
    throw new Error(
      `Research mismatch for ${competitor.company_name}`
    );
  }

  return {
    json: {
      ...competitor,
      product_research: productData.results || [],
      news_research: newsData.results || [],
      product_result_count: (productData.results || []).length,
      news_result_count: (newsData.results || []).length
    }
  };
});

const profiles = $input.all();

const research = $('Consolidate Competitor Research')
  .all()
  .map(item => item.json);

// Match research to each competitor by company name
const researchByCompany = new Map(
  research.map(r => [
    String(r.company_name).trim().toLowerCase(),
    r
  ])
);

return profiles.map((item, index) => {
  const profile = item.json;

  const name = String(profile.company_name || '')
    .trim().toLowerCase();

  const original = researchByCompany.get(name);

  if (!original) {
    throw new Error(
      `No research found for ${profile.company_name}`
    );
  }

  // Gather original Tavily research sources
  const sources = [
    ...(original.product_research || []),
    ...(original.news_research || [])
  ];

  const normalizeUrl = url =>
    String(url || '').trim().replace(/\/+$/, '');

  const knownUrls = new Set(
    sources.map(s => normalizeUrl(s.url)).filter(Boolean)
  );

  const citedUrls = Array.isArray(profile.source_urls)
    ? profile.source_urls
    : [];

  // Check whether extracted URLs exist in Tavily results
  const matched = citedUrls.filter(url =>
    knownUrls.has(normalizeUrl(url))
  );

  const unmatched = citedUrls.filter(url =>
    !knownUrls.has(normalizeUrl(url))
  );

  // Check extracted data completeness
  const featureCount = Array.isArray(profile.core_features)
    ? profile.core_features.length : 0;

  const newsCount = Array.isArray(profile.recent_news)
    ? profile.recent_news.length : 0;

  return {
    json: {
      ...profile,
      validation: {
        status:
          unmatched.length > 0 || matched.length === 0
            ? "Needs Review"
            : "Preliminary Pass",
        total_research_sources: sources.length,
        matched_source_urls: matched,
        unverified_source_urls: unmatched,
        feature_count: featureCount,
        news_count: newsCount,
        has_pricing_information: Boolean(
          profile.pricing?.model ||
          profile.pricing?.published_prices?.length
        )
      }
    },
    pairedItem: { item: index }
  };
});

