const profileItems =
  $('Agent 3 - Intelligence Extraction').all();

const reportItems = $input.all();

// Parse JSON stored inside the output field
function parseItem(item) {
  let data = item.json;

  if (data.output !== undefined) {
    data = data.output;
  }

  if (typeof data === 'string') {
    data = data.trim()
      .replace(/^```(?:json)?\s*/i, '')
      .replace(/\s*```$/, '');

    data = JSON.parse(data);
  }

  if (!data || typeof data !== 'object') {
    throw new Error('Invalid JSON object');
  }

  return data;
}

const profiles = profileItems.map(parseItem);
const reports = reportItems.map(parseItem);

// Normalize company names
const normalize = value =>
  String(value || '').trim().toLowerCase();

// Create lookup for validation reports
const reportMap = new Map();

for (const report of reports) {
  const name = normalize(report.company_name);

  if (!name) {
    throw new Error(
      'Validation report missing company_name'
    );
  }

  if (reportMap.has(name)) {
    throw new Error(
      `Duplicate validation report: ${name}`
    );
  }

  reportMap.set(name, report);
}

// Combine each profile with its validation report
const combined = profiles.map(profile => {
  const name = normalize(profile.company_name);

  if (!name) {
    throw new Error(
      'Competitor profile missing company_name'
    );
  }

  const report = reportMap.get(name);

  if (!report) {
    throw new Error(
      `No validation report for ${profile.company_name}`
    );
  }

  return {
    ...profile,
    claim_verification: report
  };
});

// Check completeness
if (combined.length !== 3) {
  throw new Error(
    `Expected 3 competitors; received ${combined.length}`
  );
}


const inputs = $('Edit Fields').first().json;

return [{
  json: {
    target_company: inputs.company,
    industry: inputs.industry,
    news_days: inputs.news_days,
    competitor_count: combined.length,
    competitors: combined,
    report_type: "Competitive Intelligence Briefing"
  }
}];

const items = $input.all();

return items.map((item, index) => {
  let report = item.json.output ?? item.json;

  // Convert JSON-formatted text into a JSON object
  if (typeof report === 'string') {
    report = report.trim()
      .replace(/^```(?:json)?\s*/i, '')
      .replace(/\s*```$/, '');

    try {
      report = JSON.parse(report);
    } catch (error) {
      throw new Error(
        `Unable to parse Agent 5 report: ${error.message}`
      );
    }
  }

  // Validate essential report fields
  const required = [
    'target_company',
    'executive_summary',
    'competitor_comparison',
    'swot_analysis',
    'strategic_recommendations'
  ];

  const missing = required.filter(
    field => report[field] === undefined
  );

  if (missing.length > 0) {
    throw new Error(
      `Missing report fields: ${missing.join(', ')}`
    );
  }

  if (!Array.isArray(report.competitor_comparison)) {
    throw new Error(
      'competitor_comparison must be an array'
    );
  }

  if (report.competitor_comparison.length !== 3) {
    throw new Error(
      'Expected 3 competitor comparison records'
    );
  }

  return {
    json: {
      ...report,
      report_status: "Generated - Pending Final Review"
    },
    pairedItem: { item: index }
  };
});
;

